def unit_of_work(metadata=None, timeout=None):
    def decorator(function):
        def wrapper(tx):
            # Set metadata and timeout if specified
            if metadata:
                tx.set_tx_metadata(metadata)
            if timeout is not None:
                tx.set_tx_timeout(timeout)
            # Execute the transaction
            try:
                result = function(tx)
            finally:
                # Ensure the transaction is closed, even if an exception occurs
                tx.close()
            return result
        return wrapper
    return decorator

