def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    for cls in classes:
        if cls not in seen:
            yield cls
            seen.add(cls)
            for base in cls.__bases__:
                yield from minimalBases(base)

    def bases(cls):
        return list(minimalBases(cls))

    def subclasses(cls):
        return (base for base in bases(cls) if isinstance(base, cls))

    def mro(cls):
        bases = list(reversed(list(mro(base)) for base in bases(cls)))
        return [cls] + bases

