def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for manifest in app.spec.manifest:
        if "observer" in manifest:
            continue
        resource_type = manifest.get("kind")
        if resource_type in ("Deployment", "DaemonSet", "StatefulSet"):
            desired_status = "Available" if resource_type == "Deployment" else "Ready"
            manifest["observer"] = {
                "shouldForce": False,
                "isReady": {
                    "resourceName": resource_type,
                    "jsonPath": f"{{{'.status.conditions[:?(@.type=="Available")].status| .[]' if resource_type == 'Service' else '.status.conditions[:?(@.type=="Ready")].status| .[]'}}}",
                    "desiredState": desired_status,
                },
            }
        elif resource_type == "Service":
            manifest["observer"] = {
                "shouldForce": False,
                "isReady": {
                    "resourceName": "Endpoint",
                    "jsonPath": "{@.subsets}| .[]",
                    "desiredState": "ContainersReady",
                },
            }
        elif resource_type == "Job":
            manifest["observer"] = {
                "shouldForce": False,
                "isReady": {
                    "resourceName": "Job",
                    "jsonPath": "{@.status.conditions[:?(@.type=="Complete")].status!='False'}",
                    "desiredState": "Complete",
                },
            }
        else:
            continue

    return app

