    # Find all digests in manifest files
    manifest_digests = set()
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as f:
            for line in f:
                if line.startswith('__ARCHIVE_BELOW__'):
                    break
                parts = line.split()
                if len(parts) < 2 or not parts[1].startswith('__'):
                    continue
                manifest_digests.add(parts[1])

    # Find all digests used in the repo
    used_digests = set()
    for digest_dir in digests_used:
        for digest_file in digest_dir.iterdir():
            if digest_file.name.startswith('__'):
                used_digests.add(digest_file.name.lstrip('_'))

    # Check if any digests are missing or unused
    missing_digests = manifest_digests - used_digests
    unused_digests = used_digests - manifest_digests

    if missing_digests:
        raise ValueError(f"The following digests are missing: {', '.join(missing_digests)}")
    if unused_digests:
        raise ValueError(f"The following digests are unused: {', '.join(unused_digests)}")

