                if not filepath.startswith("data/objects/") or not filepath.endswith(".data"):
                    raise ValueError("File path must start with 'data/objects/' and end with '.data'")

                if not os.path.exists(filepath):
                    raise ValueError("File path does not exist")

                digest = info.get("digest")
                if not isinstance(digest, str):
                    raise ValueError("Digest must be a string")

                if digest not in manifest_files:
                    raise ValueError("Digest for file {filepath} is not in the manifest")

        # Check that all manifest files have a fixity entry
        for filepath in manifest_files:
            if not any(info.get("filepath") == filepath for info in fixity[algorithm]):
                raise ValueError("File {filepath} is in the manifest but has no fixity entry")

