def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extract the values of number and supplement from the issue element.

    :param issue: The issue element.
    :return: A tuple containing the number and supplement values.
    """
    number = None
    supplement = None

    # Extract number
    if issue.isdigit():
        number = issue
    elif issue.startswith('s') and issue.lstrip('s').isdigit():
        number = issue.lstrip('s')
    elif issue.startswith('spe') and issue.lstrip('spe').isdigit():
        number = issue.lstrip('spe')
    elif issue.startswith('suppl') and issue.lstrip('suppl').isdigit():
        number = issue.lstrip('suppl')

    # Extract supplement
    if 'Suppl' in issue:
        supplement = issue.split('Suppl')[1].strip().rstrip('.').strip()
    elif 'suppl' in issue:
        supplement = issue.split('suppl')[1].strip().rstrip('.').strip()
    elif 'spe' in issue:
        supplement = issue.split('spe')[1].strip().rstrip('.').strip()
    elif 'special' in issue:
        supplement = issue.split('special')[1].strip().rstrip('.').strip()

    return number, supplement

def _extract_number_and_supplement_from_issue_element(issue):
    number = None
    supplement = None

    # Remove whitespace and punctuation
    issue = issue.strip().lower().replace('.', '').replace(',', '').replace('-', '')

    # Check for supplement first
    if 'spe' in issue:
        supplement = issue.split(' ')[0]
    elif 'suppl' in issue:
        supplement = issue.split(' ')[0]

    # Check for number second
    if 'spe' in issue:
        number = issue.split(' ')[-1]
    elif 'suppl' in issue:
        number = issue.split(' ')[-1]

    return number, supplement

