def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Generate a function to concatenate the pieces with the appropriate delimiter
    if style == 'semver':
        delimiter = '.'
    elif style == 'pvp':
        delimiter = "."
    elif style == 'post':
        delimiter = '-'
    elif style == 'dev':
        delimiter = '.'
    else:
        raise ValueError("Unsupported style: %s" % style)

    def concat_pieces(pieces):
        return delimiter.join(pieces)

    # Generate a function to format each piece before concatenation
    if style == 'semver':
        def format_piece(piece):
            if isinstance(piece, int):
                return str(piece)
            elif isinstance(piece, str):
                return piece
            else:
                raise ValueError("Invalid piece: %s" % piece)
    elif style == 'pvp':
        def format_piece(piece):
            if isinstance(piece, int):
                return str(piece)
            elif isinstance(piece, str):
                return piece
            else:
                raise ValueError("Invalid piece: %s" % piece)
    elif style == 'post':
        def format_piece(piece):
            if isinstance(piece, int):
                return str(piece)
            elif isinstance(piece, str):
                return 'post' + piece
            else:
                raise ValueError("Invalid piece: %s" % piece)
    elif style == 'dev':
        def format_piece(piece):
            if isinstance(piece, int):
                return str(piece)
            elif isinstance(piece, str):
                return 'dev' + piece
            else:
                raise ValueError("Invalid piece: %s" % piece)

    # Call the format_piece function on each piece and concatenate the results
    formatted_pieces = [format_piece(piece) for piece in pieces]
    return concat_pieces(formatted_pieces)

