def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    if validate_objects:
        for obj in self._hierarchy:
            num_objects += 1
            if obj.is_valid():
                good_objects += 1
    if check_digests:
        for obj in self._hierarchy:
            if not obj.digest_check():
                raise Exception('Digest check failed for object: {}'.format(obj))
    if show_warnings:
        for obj in self._hierarchy:
            if not obj.is_valid():
                print('Warning: Object {} is not valid'.format(obj))

    return (num_objects, good_objects)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    if validate_objects:
        for object_id in self._objects:
            num_objects += 1
            if self._objects[object_id].is_valid():
                good_objects += 1
            elif show_warnings:
                print(f"WARNING: Invalid object {object_id} found in hierarchy.")
    if check_digests:
        for object_id in self._objects:
            for child_id in self._objects[object_id].get_child_ids():
                if child_id not in self._objects:
                    if show_warnings:
                        print(f"WARNING: Object {child_id} not found in hierarchy but referenced by {object_id}.")
        for object_id in self._objects:
            for parent_id in self._objects[object_id].get_parent_ids():
                if parent_id not in self._objects:
                    if show_warnings:
                        print(f"WARNING: Object {parent_id} not found in hierarchy but referenced by {object_id}.")
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    hierarchy_objects = self.hierarchy.objects_in_hierarchy()
    for hierarchy_object in hierarchy_objects:
        num_objects += 1
        if validate_objects:
            if not hierarchy_object.object.validate():
                if show_warnings:
                    print(f"Object {hierarchy_object.object.id} failed validation")
                continue
        if check_digests:
            if not self.hierarchy.compare_digests(hierarchy_object.object.digest, hierarchy_object.object.digest):
                if show_warnings:
                    print(f"Object {hierarchy_object.object.id} has a different digest")
                continue
        good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for obj in self.hierarchy:
        num_objects += 1
        if self.hierarchy[obj].get('parent') not in self.hierarchy:
            if show_warnings:
                print(f"Object {obj} has parent {self.hierarchy[obj]['parent']} which does not exist")
            continue
        if validate_objects and not self.validate_object(obj):
            if show_warnings:
                print(f"Object {obj} did not pass validation")
            continue
        if check_digests and not self.check_digest(obj):
            if show_warnings:
                print(f"Object {obj} did not have a valid digest")
            continue
        good_objects += 1
    return num_objects, good_objects

