def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    for bug_id in bug_ids:
        result = self.request('bug/%s' % bug_id, 'GET')
        if 'error' not in result:
            bug = self.get(bug_id)
            for k in params:
                if k not in bug.params:
                    bug.params[k] = params[k]
            self.update(bug)
        else:
            raise BugsyException(result['message'])

def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        if node not in merged_nodes:
            merged_nodes.append(node)
        else:
            index = merged_nodes.index(node)
            existing_node = merged_nodes[index]
            if isinstance(existing_node.value, ruamel.yaml.nodes.MappingNode) and isinstance(node.value, ruamel.yaml.nodes.MappingNode):
                existing_node.value = deep_merge_nodes([existing_node.value, node.value])
    return merged_nodes

def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        key, value = node
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            existing_node_value = next((n[1] for n in merged_nodes if n[0] == key), None)
            if existing_node_value is not None:
                value = deep_merge_nodes([(key, existing_node_value), node])
        merged_nodes.append((key, value))
    return merged_nodes

def deep_merge_nodes(nodes):
    result = {}
    for node in nodes:
        if node[0] in result:
            if isinstance(node[1], MappingNode):
                result[node[0]] = deep_merge_nodes([(k, v) for k, v in result[node[0]].items()] + [(k, v) for k, v in node[1].items()])
