def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet)

    if number == 0:
        return alphabet[0]

    base = len(alphabet)
    result = ""
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    return result.rjust(padding, alphabet[0])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if len(alphabet) == 1:
        raise ValueError("alphabet must contain at least two elements")
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer")
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")

    base = len(alphabet)
    if number == 0:
        return alphabet[0]
    result = ""
    while number > 0:
        remainder = number % base
        number //= base
        result = alphabet[remainder] + result
    if padding is not None:
        result = result.rjust(padding, alphabet[0])
    return result

