        unit = pluralize(unit)
        if unit not in FREQUENCY_UNITS:
            raise ValueError("Invalid frequency unit: %s" % unit)
        return datetime.timedelta(**{unit: int(num)})
    except ValueError:
        raise ValueError("Invalid frequency: %s" % frequency)

