    """Call the given command(s)."""

    if isinstance(commands, str):
        commands = [commands]

    if not isinstance(args, list):
        raise TypeError("Expected a list of arguments, got {}".format(type(args)))

    if cwd is not None:
        if not isinstance(cwd, str):
            raise TypeError("Expected a string for cwd, got {}".format(type(cwd)))
        cwd = os.path.abspath(cwd)

    if verbose:
        print("Running command {} with args {}".format(commands, args))

    if hide_stderr:
        output = subprocess.check_output(commands, stderr=subprocess.STDOUT, cwd=cwd, env=env)
    else:
