def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    output = []
    for command in commands:
        if verbose:
            print(f"Running command: {command}")
        try:
            result = subprocess.run(
                command,
                args=args,
                cwd=cwd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=env,
            )
            output.append(result.stdout.decode("utf-8"))
            if not hide_stderr:
                output.append(result.stderr.decode("utf-8"))
        except subprocess.CalledProcessError as e:
            output.append(e.stdout.decode("utf-8"))
            output.append(e.stderr.decode("utf-8"))
    return output

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        cmd = [command]
        cmd.extend(args)

        if verbose:
            print(f"Running command: {' '.join(cmd)}")

        process = subprocess.Popen(cmd,
                                   stdout=subprocess.PIPE,
                                   stderr=subprocess.PIPE,
                                   cwd=cwd,
                                   env=env)
        stdout, stderr = process.communicate()

        if process.returncode != 0:
            raise RuntimeError(f"Command {' '.join(cmd)} failed with exit code {process.returncode}.")

        if not hide_stderr and stderr:
            print(stderr.decode())

        if stdout:
            print(stdout.decode())

        return process.returncode

