def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if not roots:
        roots = set()
    for node in graph.subjects(prop, None):
        if node not in roots:
            roots.add(node)
    for node, _ in graph.subject_objects(prop):
        if node in roots:
            roots.remove(node)
    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    # Find nodes that are not parents
    for subj, _, obj in graph.triples((None, prop, None)):
        if (subj, prop, obj) not in graph and (obj, prop, subj) not in graph:
            roots.add(subj)
    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    nodes = set()
    edges = graph.subject_objects(prop)
    if not roots:
        roots = set()
        for edge in edges:
            nodes.add(edge[0])
            if edge[1] not in roots:
                roots.add(edge[1])
        for node in nodes:
            if all(edge[1] not in roots for edge in edges if edge[0] == node):
                roots.add(node)
    return roots

