def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is None:
        return {version_tuple: cls.PROTOCOL_HANDLERS[version_tuple]
                for version_tuple in cls.PROTOCOL_HANDLERS}

    if not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be a tuple")

    if protocol_version not in cls.PROTOCOL_HANDLERS:
        raise ValueError(f"Protocol version {protocol_version} is not supported")

    return {protocol_version: cls.PROTOCOL_HANDLERS[protocol_version]}

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    supported_versions = {
        (3, 5): cls.Bolt35ProtocolHandler,
        (4, 0): cls.Bolt40ProtocolHandler,
        (4, 1): cls.Bolt41ProtocolHandler,
        (4, 2): cls.Bolt42ProtocolHandler,
        (4, 3): cls.Bolt43ProtocolHandler,
    }

    if protocol_version:
        if protocol_version in supported_versions:
            return {protocol_version: supported_versions[protocol_version]}
        else:
            return {}
    else:
        return supported_versions

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        handlers = {}
        for handler in cls._available_handlers:
            version = handler.get_version()
            handlers[version] = handler
        return handlers
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError('protocol_version must be passed in a tuple')
        version = protocol_version[0]
        handler = cls._available_handlers.get(version)
        if handler is None:
            return {}
        else:
            return {version: handler}

