def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale'):
            self._scale = self.histogram.sum()
        return self._scale

    if self._scale == 0:
        raise LenaValueError("Can not rescale histogram with zero scale.")

    self.histogram /= self._scale
    self._scale = other
    self.histogram *= self._scale

    return self._scale

def verifyObject(iface, candidate, tentative=False):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(f"Invalid candidate: {candidate!r} does not provide {iface.get('name')!r}")

    methods = iface.get('methods')
    for method in methods:
        method_name = method.get('name')
        method_spec = method.get('spec')
        method_from_candidate = getattr(candidate, method_name)

        if not callable(method_from_candidate):
            raise zope.interface.Invalid(f"Invalid candidate: {candidate!r} does not have a callable method {method_name!r}")

        if method_spec and not signature_matches(method_from_candidate, method_spec):
            raise zope.interface.Invalid(f"Invalid candidate: {candidate!r} does not have a method {method_name!r} that matches the spec")

    attributes = iface.get('attributes')
    for attribute in attributes:
        attribute_name = attribute.get('name')
        attribute_spec = attribute.get('spec')
        attribute_from_candidate = getattr(candidate, attribute_name)

        if not isinstance(attribute_from_candidate, attribute_spec):
            raise zope.interface.Invalid(f"Invalid candidate: {candidate!r} does not have an attribute {attribute_name!r} that matches the spec")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate implements the interface
    if not hasattr(candidate, iface):
        raise RuntimeError("Candidate class does not implement the interface")

    # Check if the candidate's implementation satisfies the interface
    for method in iface._methods:
        if not hasattr(candidate, method):
            raise RuntimeError(f"Candidate class does not implement {method} method")

        candidate_method = getattr(candidate, method)
        iface_method = getattr(iface, method)

