def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not isinstance(public_key, RSAPublicKey):
        raise ValueError("Expected RSAPublicKey instance, got %s" % type(public_key))

    if not isinstance(doc, etree._Element):
        raise ValueError("Expected etree._Element instance, got %s" % type(doc))

    if not isinstance(signature, bytes):
        raise ValueError("Expected bytes instance, got %s" % type(signature))

    # Verify the signature
    try:
        pubkey = RSA.importKey(public_key)
        pubkey.verify(signature, doc.serialize(), hashlib.sha256)
        return True
    except InvalidSignature:
        return False

