def ansible_playbook(self, playbook_path: str, verbose: int = None, extra_vars: dict = None, ansible_args: dict = None) -> Union[AnsiblePlaybook, ActionResult]:
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    if playbook_path is None:
        raise ValueError("playbook_path must be a valid absolute path to a playbook file")

    ansible_playbook = self._get_ansible_playbook(playbook_path, verbose=verbose, extra_vars=extra_vars, ansible_args=ansible_args)

    if not ansible_playbook:
        return ActionResult(message="Could not execute playbook.", status="FAILED", output_json=None)

    result = ansible_playbook.execute_playbook()

    return ActionResult(message=result.stdout, status=result.status, output_json=result.output_json)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for name, value in values_dict.items():
        try:
            values_dict[name] = getattr(self, parser_name).get_option_type(name)(value)
        except Exception as e:
            print(f"Failed to convert argument {name} to correct type: {value}->{str(e)}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    for opt in self.cmd_options(parser_name):
        if opt.name in values_dict and values_dict[opt.name] is not None:
            try:
                values_dict[opt.name] = opt.convert(values_dict[opt.name])
            except ValueError:
                raise CLIParamException(
                    f"Invalid value '{values_dict[opt.name]}' for parameter '{opt.name}'")

