def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    with open(os.path.join(plugin_dir, 'plugin.spec'), 'r') as f:
        plugin_spec = yaml.safe_load(f)
    flat_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            flat_dict.update({key: value})
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    flat_dict.update({key: item})
                else:
                    flat_dict.update({key: value})
        else:
            flat_dict.update({key: value})
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec_path = os.path.join(plugin_dir, "plugin.spec.yaml")
    with open(plugin_spec_path, "r") as f:
        plugin_spec = yaml.safe_load(f)
    return {
        **plugin_spec.get("metadata", {}),
        **{
            k: v
            for k, v in plugin_spec.get("service", {}).items()
            if k not in ("spec", "env")
        },
        **{
            k: v
            for k, v in plugin_spec.get("service", {}).get("spec", {}).items()
            if k not in ("spec", "env")
        },
    }

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = self._get_plugin_spec_dict(plugin_dir)
    flat_dict = {}
    for key, value in plugin_spec.items():
        flat_dict[key] = value
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flat_dict[f"{key}.{sub_key}"] = sub_value
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = PluginSpec(plugin_dir)
    spec_dict = plugin_spec.to_dict()
    flatten_dict = {}
    for key, value in spec_dict.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[key + "." + subkey] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict

